assignments.value:
=Classify the following email.
From domain: {{$json.sender_domain}} 
Subject: {{$json.subject_clean}} 
Body: {{$json.body_clean}}  
Return a single JSON object following the rules in the system prompt. 
Return only: {"category":"...","confidence":...,"reasoning":"...","suggested_priority":...}
No other text.

parameters.jsCode:
const item = $json;

// 1. Clean Subject
const subject_clean = (item.subject || '')
  .replace(/^(Re:|Fwd:|FW:|RE:|FWD:|AW:|Aw:)\s*/gi, '').trim();

// 2. Clean Body
let body = item.body || '';

// Remove reply chains
const replyStopPatterns = [
  /On .{5,130}(wrote:|écrit:)/s,
  /-----+\s*(Original Message|Forwarded Message|BEGIN)\s*-----+/i,
 /^From:\s.*$\n^Sent:\s.*$/gim
];
for (const p of replyStopPatterns) {
  const idx = body.search(p);
  if (idx > 40) { body = body.substring(0, idx); break; }
}

// Remove signatures
const sigStopPatterns = [
  /\n--\s*\n/i,
  /\n(Best regards|Kind regards|Warm regards|Regards|Sincerely|Cheers)\s*,?\s*\n/i,
  /\n[-—]{3,}/
];
for (const p of sigStopPatterns) {
  const idx = body.search(p);
  if (idx > 20) { body = body.substring(0, idx); break; }
}

const body_clean = body
// Normalize whitespace while preserving readability
  .replace(/[ \t]+/g, " ")
  .replace(/\n{3,}/g, "\n\n")
  .trim();



// 3. Extract email/name from From field
const sender_email = (item.from_email || "").toLowerCase();

const sender_domain = sender_email.split("@")[1] || "";

const sender_name = (item.from_name || "").trim();

const sender_first_name = sender_name.split(/\s+/)[0] || "";

// 4. Preview
const body_preview = body_clean.substring(0, 500);

return {
  ...item,
  subject_clean,
  body_clean,
  body_preview,
  sender_email,
  sender_domain,
  sender_name,
  sender_first_name
};

const item = $input.item.json;
const original = $('Clean Email').item.json;
let parse_failed = false;
let parsed;

try {
  const raw =
    item.output?.[1]?.content?.[0]?.text   // Responses API
    ?? item.choices?.[0]?.message?.content  // Chat Completions API
    ?? item.text
    ?? "";


  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch {
  parse_failed = true;
  parsed = { category: "OTHER", confidence: 0, reasoning: "Failed to parse model response.", suggested_priority: null };
}

const ALLOWED_CAT = ["LEAD", "SUPPORT", "SPAM", "OTHER"];
const ALLOWED_PRI = ["LOW", "MEDIUM", "HIGH"];

if (!ALLOWED_CAT.includes(parsed.category)) { parsed.category = "OTHER"; parse_failed = true; }

parsed.confidence = Math.max(0, Math.min(1, Number(parsed.confidence) || 0));
parsed.reasoning = typeof parsed.reasoning === "string" ? parsed.reasoning.slice(0, 300) : "No reasoning provided.";

if (parsed.category !== "LEAD") {
  parsed.suggested_priority = null;
} else if (!ALLOWED_PRI.includes(parsed.suggested_priority)) {
  parsed.suggested_priority = "MEDIUM";
}
return {
  ...original,
  classification: {
    category: parsed.category,
    confidence: parsed.confidence,
    reasoning: parsed.reasoning,
    suggested_priority: parsed.suggested_priority
  },
  parse_failed,
  classified_at: new Date().toISOString()
};

assignments.value:
=Generate a lead follow-up email.  
Sender Name: {{ $('Route by category1').item.json.sender_first_name }}  
Sender Domain: {{ $('Route by category1').item.json.sender_domain }}  
Priority: {{ $('Route by category1').item.json.classification.suggested_priority }} Subject: {{ $('Route by category1').item.json.subject_clean }}  
Email Body: {{ $('Route by category1').item.json.body_clean }}  
Signature: {{ $json.fixed_signature }}

parameters.jsCode:
const priorityScore = { HIGH: 1.0, MEDIUM: 0.6, LOW: 0.3 };
const classification = $('Parse classification').item.json.classification;
const priority = classification.suggested_priority || 'LOW';
const confidence = classification.confidence || 0;
const leadScore = Math.round(confidence * (priorityScore[priority] || 0.3) * 100);

const processingMs = Date.now() - ($('Track Execution Metadata').item.json.processing_start_ms || Date.now());

return [{
  json: {
    ...$input.item.json,
    lead_score: leadScore,
    lead_score_label: leadScore >= 70 ? 'HOT' : leadScore >= 40 ? 'WARM' : 'COLD',
    processing_ms: processingMs
  }
}];
